import{_ as l,a0 as g,w as o,s as r,ao as p,I as n,x as a,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Sysget：给主流的包管理器加个前端 | LCTT x X-CMD","titleTemplate":false,"description":"Sysget：给主流的包管理器加个前端 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Sysget：给主流的包管理器加个前端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Sysget：给主流的包管理器加个前端 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20181011 A Front-end For Popular Package Managers","title":"Sysget：给主流的包管理器加个前端","tag":"201810","desc":""},"relativePath":"201810/20181011 A Front-end For Popular Package Managers.md","filePath":"[post].md"}'),d={name:"201810/20181011 A Front-end For Popular Package Managers.md"};function h(u,s,c,k,b,y){const e=g("Link");return o(),r("div",null,[s[18]||(s[18]=p('<h1 id="sysget-给主流的包管理器加个前端" tabindex="-1">Sysget：给主流的包管理器加个前端 <a class="header-anchor" href="#sysget-给主流的包管理器加个前端" aria-label="Permalink to “Sysget：给主流的包管理器加个前端”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/sysget-720x340.png" alt=""></p><p>你是一个喜欢每隔几天尝试 Linux 操作系统的新发行版的发行版收割机吗？如果是这样，我有一些东西对你有用。 尝试 Sysget，这是一个类 Unix 操作系统中的流行软件包管理器的前端。 你不需要学习每个包管理器来执行基本的操作，例如安装、更新、升级和删除包。 你只需要对每个运行在类 Unix 操作系统上的包管理器记住一种语法即可。 Sysget 是包管理器的包装脚本，它是用 C++ 编写的。 源代码可在 GitHub 上免费获得。</p><p>使用 Sysget，你可以执行各种基本的包管理操作，包括：</p><ul><li>安装包，</li><li>更新包，</li><li>升级包，</li><li>搜索包，</li><li>删除包，</li><li>删除弃用包，</li><li>更新数据库，</li><li>升级系统，</li><li>清除包管理器缓存。</li></ul><p><strong>给 Linux 学习者的一个重要提示：</strong></p><p>Sysget 不会取代软件包管理器，绝对不适合所有人。如果你是经常切换到新 Linux 操作系统的新手，Sysget 可能会有所帮助。当在不同的 Linux 发行版中使用不同的软件包管理器时，就必须学习安装、更新、升级、搜索和删除软件包的新命令，这时 Sysget 就是帮助<ruby>发行版收割机<rt>distro hopper</rt></ruby>（或新 Linux 用户）的包装脚本。</p><p>如果你是 Linux 管理员或想要学习 Linux 深层的爱好者，你应该坚持使用你的发行版的软件包管理器并学习如何使用它。</p><h3 id="安装-sysget" tabindex="-1">安装 Sysget <a class="header-anchor" href="#安装-sysget" aria-label="Permalink to “安装 Sysget”">​</a></h3>',9)),n("p",null,[s[1]||(s[1]=a("安装 Sysget 很简单。 转到",-1)),i(e,{href:"https://github.com/emilengler/sysget/releases"},{default:t(()=>[...s[0]||(s[0]=[a("发布页面",-1)])]),_:1}),s[2]||(s[2]=a("并下载最新的 Sysget 二进制文件并按如下所示进行安装。 在编写本指南时，Sysget 最新版本为1.2。",-1))]),s[19]||(s[19]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo wget -O /usr/local/bin/sysget https://github.com/emilengler/sysget/releases/download/v1.2/sysget</span></span>
<span class="line"><span>$ sudo mkdir -p /usr/local/share/sysget</span></span>
<span class="line"><span>$ sudo chmod a+x /usr/local/bin/sysget</span></span></code></pre></div><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>Sysget 命令与 APT 包管理器大致相同，因此它应该适合新手使用。</p><p>当你第一次运行 Sysget 时，系统会要求你选择要使用的包管理器。 由于我在 Ubuntu，我选择了 apt-get。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/sysget-1.png" alt=""></p><p>你必须根据正在运行的发行版选择正确的包管理器。 例如，如果你使用的是 Arch Linux，请选择 pacman。 对于 CentOS，请选择 yum。 对于 FreeBSD，请选择 pkg。 当前支持的包管理器列表是：</p><ol><li>apt-get (Debian)</li><li>xbps (Void)</li><li>dnf (Fedora)</li><li>yum (Enterprise Linux/Legacy Fedora)</li><li>zypper (OpenSUSE)</li><li>eopkg (Solus)</li><li>pacman (Arch)</li><li>emerge (Gentoo)</li><li>pkg (FreeBSD)</li><li>chromebrew (ChromeOS)</li><li>homebrew (Mac OS)</li><li>nix (Nix OS)</li><li>snap (Independent)</li><li>npm (Javascript, Global)</li></ol><p>如果你分配了错误的包管理器，则可以使用以下命令设置新的包管理器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget set yum</span></span>
<span class="line"><span>Package manager changed to yum</span></span></code></pre></div><p>只需确保你选择了本地包管理器。</p><p>现在，你可以像使用本机包管理器一样执行包管理操作。</p><p>要安装软件包，例如 Emacs，只需运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget install emacs</span></span></code></pre></div><p>上面的命令将调用本机包管理器（在我的例子中是 “apt-get”）并安装给定的包。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/Install-package-using-Sysget.png" alt=""></p><p>同样，要删除包，只需运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget remove emacs</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/Remove-package-using-Sysget.png" alt=""></p><p>更新软件仓库（数据库）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget update</span></span></code></pre></div><p>搜索特定包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget search emacs</span></span></code></pre></div><p>升级单个包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget upgrade emacs</span></span></code></pre></div><p>升级所有包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget upgrade</span></span></code></pre></div><p>移除废弃的包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget autoremove</span></span></code></pre></div><p>清理包管理器的缓存：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo sysget clean</span></span></code></pre></div><p>有关更多详细信息，请参阅帮助部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sysget help</span></span>
<span class="line"><span>Help of sysget</span></span>
<span class="line"><span>sysget [OPTION] [ARGUMENT]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>search [query] search for a package in the resporitories</span></span>
<span class="line"><span>install [package] install a package from the repos</span></span>
<span class="line"><span>remove [package] removes a package</span></span>
<span class="line"><span>autoremove removes not needed packages (orphans)</span></span>
<span class="line"><span>update update the database</span></span>
<span class="line"><span>upgrade do a system upgrade</span></span>
<span class="line"><span>upgrade [package] upgrade a specific package</span></span>
<span class="line"><span>clean clean the download cache</span></span>
<span class="line"><span>set [NEW MANAGER] set a new package manager</span></span></code></pre></div><p>请记住，不同 Linux 发行版中的所有包管理器的 Sysget 语法都是相同的。 你不需要记住每个包管理器的命令。</p><p>同样，我必须告诉你 Sysget 不是包管理器的替代品。 它只是类 Unix 系统中流行的包管理器的包装器，它只执行基本的包管理操作。</p><p>Sysget 对于不想去学习不同包管理器的新命令的新手和发行版收割机用户可能有些用处。 如果你有兴趣，试一试，看看它是否有帮助。</p><p>而且，这就是本次所有的内容了。 更多干货即将到来。 敬请关注！</p><p>祝快乐！</p><hr>`,38)),n("p",null,[s[4]||(s[4]=a("via: ",-1)),i(e,{href:"https://www.ostechnix.com/sysget-a-front-end-for-popular-package-managers/"},{default:t(()=>[...s[3]||(s[3]=[a("https://www.ostechnix.com/sysget-a-front-end-for-popular-package-managers/",-1)])]),_:1})]),n("p",null,[s[9]||(s[9]=a("作者：",-1)),i(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[5]||(s[5]=[a("SK",-1)])]),_:1}),s[10]||(s[10]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),i(e,{href:"https://github.com/Flowsnow"},{default:t(()=>[...s[7]||(s[7]=[a("Flowsnow",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const C=l(d,[["render",h]]);export{x as __pageData,C as default};
